document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let visible=0;document.querySelectorAll('.product').forEach(p=>{const show=button.dataset.filter==='featured'?p.dataset.featured==='true':p.dataset.category===button.dataset.filter;p.hidden=!show;if(show)visible++;});document.querySelector('#product-status').textContent=`${visible} ${button.textContent} products`;}));
